import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { db } from "../lib/db";

const exec = promisify(execFile);

const CHAIN = process.env.NXEON_NAT_CHAIN ?? "NXEON_FWD";

async function iptables(args: string[]) {
  await exec("iptables", args);
}

async function ensureChain() {
  try {
    await iptables(["-t", "nat", "-N", CHAIN]);
  } catch {
    /* chain exists */
  }
  // Ensure PREROUTING jumps to our chain exactly once
  try {
    await iptables(["-t", "nat", "-C", "PREROUTING", "-j", CHAIN]);
  } catch {
    await iptables(["-t", "nat", "-A", "PREROUTING", "-j", CHAIN]);
  }
}

/** Rebuild the entire NXEON_FWD chain from the database. Idempotent. */
export async function syncPortForwards() {
  await ensureChain();
  await iptables(["-t", "nat", "-F", CHAIN]);

  const servers = await db.server.findMany({
    where: {
      ipAddress: { not: null },
      sshPort: { not: null },
      status: { notIn: ["SUSPENDED", "DELETING"] },
    },
    include: { portForwards: true },
  });

  for (const s of servers) {
    await iptables([
      "-t", "nat", "-A", CHAIN,
      "-p", "tcp", "--dport", String(s.sshPort),
      "-j", "DNAT", "--to-destination", `${s.ipAddress}:22`,
    ]);
    for (const f of s.portForwards) {
      await iptables([
        "-t", "nat", "-A", CHAIN,
        "-p", f.protocol, "--dport", String(f.publicPort),
        "-j", "DNAT", "--to-destination", `${s.ipAddress}:${f.guestPort}`,
      ]);
    }
  }
}

